const PAGE="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Evertrust Books \u00b7 Connections</title><style>\n:root{font-family:Inter,system-ui,sans-serif;color:#272136;background:#f7f5fb}*{box-sizing:border-box}body{margin:0}header{border-bottom:1px solid #e5deef;background:#fff;padding:24px max(24px,calc((100vw - 1080px)/2));display:flex;gap:16px;align-items:center}.logo{width:38px;height:38px;background:#6b409c;color:white;display:grid;place-items:center;border-radius:11px;font-weight:700}.brand{font-size:20px;font-weight:700}.sub{font-size:12px;color:#756983;margin-top:4px}.mode{margin-left:auto;border:1px solid #ded4eb;color:#65408e;border-radius:20px;padding:7px 12px;font-size:12px}main{max-width:1080px;margin:44px auto;padding:0 24px}.heading{display:flex;align-items:center;justify-content:space-between;gap:20px}h1{font-size:32px;margin:0 0 10px}p{line-height:1.6;color:#71677e;margin:0 0 18px}button{font:inherit;border-radius:8px;border:1px solid #e0d7eb;background:white;color:#50445e;padding:10px 14px;cursor:pointer}button:hover{border-color:#8a65b3}button:disabled{opacity:.55;cursor:wait}.primary{background:#6b409c;color:white;border-color:#6b409c}.danger{color:#a83752} .cards{display:flex;flex-direction:column;gap:14px;margin:24px 0}.company{background:white;border:1px solid #e5deee;border-radius:12px}.company>summary{display:flex;align-items:center;gap:12px;padding:15px 18px;cursor:pointer;list-style:none}.company>summary:before{content:'\u25be';color:#8a65b3}.company:not([open])>summary:before{content:'\u25b8'}.company>summary::-webkit-details-marker{display:none}.company h2{font-size:17px;margin:0;overflow-wrap:anywhere}.count{font-size:12px;color:#887894;margin-left:auto;white-space:nowrap}.token-row{display:grid;grid-template-columns:minmax(0,1fr) 190px auto;align-items:center;gap:16px;padding:11px 18px;border-top:1px solid #f0ebf5;min-height:67px}.token-row.selected{border-left:3px solid #9564c4;padding-left:15px}.token-title{font-size:14px;font-weight:600;overflow-wrap:anywhere}.token-label{font-size:12px;color:#74647f;margin-top:5px;overflow-wrap:anywhere}.badge{display:inline-block;font-size:11px;background:#edf8f0;color:#267648;padding:3px 7px;border-radius:10px}.badge.failed{background:#fff0f1;color:#a63851}.badge.unknown{background:#f4f0f9;color:#786687}.meta{font-size:11px;color:#8b8195;margin-top:5px;overflow-wrap:anywhere}.error{font-size:12px;color:#a63851;margin-top:5px}.row-actions{display:flex;align-items:center;gap:7px}.row-actions button,.menu>summary{font-size:12px;padding:7px 10px}.menu{position:relative}.menu>summary{list-style:none;border:1px solid #e0d7eb;border-radius:8px;cursor:pointer;white-space:nowrap}.menu>summary::-webkit-details-marker{display:none}.menu-panel{position:absolute;right:0;top:34px;z-index:5;background:white;border:1px solid #e0d7eb;border-radius:9px;box-shadow:0 8px 24px #30214020;padding:6px;min-width:190px}.menu-panel button{display:block;text-align:left;border:0;width:100%;padding:9px;font-size:12px}.menu-panel button:hover{background:#f6f1fb}.menu-panel .meta{padding:6px;max-width:240px;white-space:pre-wrap}.empty{padding:36px;text-align:center;background:white;border:1px dashed #d9cde7;border-radius:12px}.help{padding:22px;border-radius:12px;background:#efe9f6;font-size:14px;line-height:1.7;color:#5e4b74}.help b{display:block;margin-bottom:6px}dialog{border:0;border-radius:16px;max-width:520px;width:calc(100% - 32px);padding:28px;color:#272136;box-shadow:0 20px 90px #30214040}dialog::backdrop{background:#29213280}label{display:block;font-size:13px;font-weight:600;margin:16px 0 7px}input,textarea{width:100%;padding:12px;border:1px solid #d8cde4;border-radius:8px;font:inherit}textarea{resize:vertical}.footer{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}#notice{margin-top:22px;line-height:1.5;min-height:24px;color:#645174}#formError{color:#a63851;margin-top:16px;font-size:14px}.hidden{display:none}@media(max-width:600px){.heading{align-items:flex-start;flex-direction:column}.mode{display:none}main{margin-top:28px}.token-row{grid-template-columns:minmax(0,1fr) auto;gap:10px}.row-status{grid-column:1;grid-row:2}.row-actions{grid-column:2;grid-row:1 / span 2}.company>summary{padding:13px}.token-row{padding:10px 13px}.token-row.selected{padding-left:10px}h1{font-size:28px}}\n</style></head><body><header><div class=\"logo\">E</div><div><div class=\"brand\">Evertrust Books</div><div class=\"sub\">ACCOUNTING CONNECTIONS</div></div><div class=\"mode\">Reviewed COA + business tools</div></header><main><div class=\"heading\"><div><h1>Company connections</h1><p>Manage your companies and access tokens in one place.</p></div><button class=\"primary\" id=\"add\">+ Add token</button></div><div id=\"notice\" role=\"status\" aria-live=\"polite\">Loading connections\u2026</div><section id=\"cards\" class=\"cards\" aria-label=\"Tokens grouped by company\"></section><details class=\"company\" style=\"margin-bottom:24px\"><summary><h2>External COA data (optional)</h2></summary><div style=\"padding:0 18px 18px\"><p>Manage COA in ChatGPT using native accounts and groups. This optional section accepts external bulk data; review every resolved account and group ID before applying.</p><label for=\"syncConnection\">Company / token</label><select id=\"syncConnection\" style=\"width:100%;padding:10px;border:1px solid #d8cde4;border-radius:8px\"></select><label for=\"syncFile\">Excel or CSV file</label><input id=\"syncFile\" type=\"file\" accept=\".xlsx,.csv,.tsv\"><label for=\"syncInput\">Or paste a table</label><textarea id=\"syncInput\" rows=\"5\" placeholder=\"Code&#9;Name&#9;Group&#9;Report&#9;Type\"></textarea><p class=\"meta\">Existing items can be identified by Code or Name. For new items, add Report (BS / PL) and Type (Account / Group). Include a Group row to create a new parent. Only the COA sheet, or otherwise the first sheet, is imported. Formula results must be recalculated and saved before import.</p><button class=\"primary\" id=\"syncPrepare\">Prepare COA preview</button><div id=\"syncResult\" style=\"margin-top:16px\"></div><label style=\"font-weight:400\"><input id=\"syncApproval\" type=\"checkbox\" style=\"width:auto\"> I have reviewed all differences in the structured preview and approve this exact task.</label><button class=\"primary\" id=\"syncExecute\" disabled>Apply approved changes</button> <button id=\"syncRefresh\" disabled>Refresh remaining items</button><div id=\"syncProgress\" role=\"status\" aria-live=\"polite\" style=\"margin:14px 0\"></div><p class=\"meta\">Keep this page open while it runs. Saved results can be reopened after an interruption.</p><details><summary>Recent drafts and results</summary><div id=\"syncHistory\"></div></details></div></details><div class=\"help\"><b>Working with your companies</b>In ChatGPT, name the company you want to review. COA changes are prepared as a task, previewed, then executed only after your approval. Each query identifies its connection, so conversations can work with different companies independently.<br>Tokens are encrypted on the server and never displayed after saving. Removing a connection erases its saved token here. To revoke the token itself, use Settings \u2192 Access Tokens in Manager.</div></main>\n<dialog id=\"editor\"><form id=\"connectionForm\"><h2 id=\"editorTitle\">Add token</h2><p id=\"editorHint\">In Manager, open a company and go to Settings \u2192 Access Tokens. We will verify the token and read the company and token names automatically.</p><div id=\"tokenField\"><label for=\"token\">Access token</label><input id=\"token\" name=\"token\" type=\"password\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"Paste the complete Secret from Manager\"></div><label for=\"label\">Label (optional)</label><input id=\"label\" name=\"label\" maxlength=\"120\" placeholder=\"e.g. Accounting Team or Audit 2026\"><label for=\"notes\">Notes (optional)</label><textarea id=\"notes\" name=\"notes\" maxlength=\"500\" rows=\"2\" placeholder=\"Internal reference or bookkeeping notes\"></textarea><div id=\"formError\" role=\"alert\"></div><div class=\"footer\"><button type=\"button\" id=\"cancel\">Cancel</button><button class=\"primary\" id=\"save\">Verify & add</button></div></form></dialog>\n<dialog id=\"remover\"><h2>Remove connection?</h2><p id=\"removeText\"></p><p>This erases the saved token from Evertrust Books. It does not revoke the token in Manager or change any accounting records.</p><div class=\"footer\"><button id=\"keep\">Keep connection</button><button id=\"removeConfirm\" class=\"danger\">Remove connection</button></div></dialog>\n<script>\nconst $=id=>document.getElementById(id);let connections=[],selected=null,editing=null,mode='add',removing=null;\nasync function api(path,body,method){const r=await fetch(path,{method:method||(body?'POST':'GET'),headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});let d;try{d=await r.json()}catch{throw Error('The server returned an unexpected response. Please try again.')}if(!r.ok)throw Error(d.error||'Request failed');return d}\nfunction text(parent,tag,value,cls){const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;parent.append(e);return e}\nfunction action(parent,label,fn,cls){const b=text(parent,'button',label,cls);b.onclick=async()=>{b.disabled=true;try{await fn()}catch(e){$('notice').textContent=e.message}finally{b.disabled=false}}}\nfunction render(){const root=$('cards');const closed=new Set([...root.children].filter(g=>g.dataset.company&&!g.open).map(g=>g.dataset.company));root.replaceChildren();if(!connections.length){text(root,'div','No tokens connected yet. Add your first token to get started.','empty');return}const groups=new Map();for(const c of connections){const name=c.business_name||'Unknown company';if(!groups.has(name))groups.set(name,[]);groups.get(name).push(c)}for(const [name,items] of [...groups].sort((a,b)=>a[0].localeCompare(b[0],'en'))){const group=text(root,'details','','company');group.dataset.company=name;group.open=!closed.has(name);const heading=text(group,'summary','');text(heading,'h2',name);text(heading,'span',items.length+' token'+(items.length===1?'':'s'),'count');for(const c of items){const row=text(group,'article','','token-row'+(selected===c.connection_id?' selected':''));const main=text(row,'div','');text(main,'div',c.token_name||'Token name unavailable','token-title');if(c.label)text(main,'div','Label: '+c.label,'token-label');if(c.last_error)text(main,'div',c.last_error,'error');const status=text(row,'div','','row-status');text(status,'span',c.status==='connected'?'Verified':c.status==='failed'?'Needs attention':'Not tested yet','badge '+(c.status==='failed'?'failed':c.status==='unknown'?'unknown':''));const date=text(status,'div',(selected===c.connection_id?'Preferred \u00b7 ':'')+(c.verified_at?'Verified '+new Date(c.verified_at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Not verified yet'),'meta');date.title=c.verified_at?new Date(c.verified_at).toLocaleString('en-US'):'';const actions=text(row,'div','','row-actions');action(actions,'Test',async()=>{const d=await api('/api/connections/'+c.connection_id+'/test',{});await refresh();$('notice').textContent=d.ok?'Connection verified: '+d.connection.business_name+' \u00b7 '+(d.connection.token_name||'Token name unavailable'):d.connection.last_error});const menu=text(actions,'details','','menu');text(menu,'summary','More');const panel=text(menu,'div','','menu-panel');action(panel,'Edit label / notes',()=>openEditor('edit',c));action(panel,'Update token',()=>openEditor('replace',c));action(panel,selected===c.connection_id?'Preferred':'Set preferred',async()=>{await api('/api/preferred',{connection_id:c.connection_id});await refresh()});action(panel,'Remove',()=>{removing=c;$('removeText').textContent='Remove '+(c.token_name||'this token')+' from '+c.business_name+'?';$('remover').showModal()},'danger');text(panel,'div','Connection '+c.connection_id,'meta');if(c.notes)text(panel,'div','Notes: '+c.notes,'meta');if(!c.token_name)text(panel,'div','Test this connection to refresh its token name.','meta')}}}\nasync function refresh(){const d=await api('/api/connections');connections=d.connections;selected=d.preferred_connection_id;render();const select=$('syncConnection');const chosen=select.value;select.replaceChildren();const placeholder=text(select,'option','Select company / token');placeholder.value='';for(const c of connections){const option=text(select,'option',c.business_name+' / '+(c.token_name||'Unnamed token')+(c.label?' / '+c.label:''));option.value=c.connection_id}if(connections.some(c=>c.connection_id===chosen))select.value=chosen;const companies=new Set(connections.map(c=>c.business_name)).size;$('notice').textContent=companies+' compan'+(companies===1?'y':'ies')+' \u00b7 '+connections.length+' token'+(connections.length===1?'':'s')}\nfunction openEditor(next,c=null){mode=next;editing=c;$('connectionForm').reset();$('formError').textContent='';$('label').value=c?.label||'';$('notes').value=c?.notes||'';$('tokenField').classList.toggle('hidden',next==='edit');$('token').required=next!=='edit';$('editorTitle').textContent=next==='add'?'Add token':next==='edit'?'Edit connection':'Update access token';$('editorHint').textContent=next==='replace'?'The new token must identify the same company. Your current token is kept until verification succeeds.':next==='edit'?'Update the optional label and notes for this connection.':'In Manager, open a company and go to Settings \u2192 Access Tokens. We will verify the token and read the company and token names automatically.';$('save').textContent=next==='add'?'Verify & add':next==='edit'?'Save changes':'Verify & replace';$('editor').showModal()}\n$('editor').addEventListener('close',()=>{$('token').value=''});$('add').onclick=()=>openEditor('add');$('cancel').onclick=()=>{$('editor').close();$('token').value=''};$('keep').onclick=()=>$('remover').close();$('connectionForm').onsubmit=async e=>{e.preventDefault();const button=$('save');button.disabled=true;$('formError').textContent='';try{const d={label:$('label').value,notes:$('notes').value};if(mode!=='edit')d.token=$('token').value;await api(mode==='add'?'/api/connections':'/api/connections/'+editing.connection_id+(mode==='replace'?'/token':''),d);$('token').value='';$('editor').close();await refresh()}catch(e){$('formError').textContent=e.message}finally{button.disabled=false}};\n$('removeConfirm').onclick=async()=>{const b=$('removeConfirm');b.disabled=true;try{await api('/api/connections/'+removing.connection_id,{},'DELETE');$('remover').close();await refresh()}catch(e){$('notice').textContent=e.message}finally{b.disabled=false}};refresh().catch(e=>$('notice').textContent=e.message);\n// Excel files are decoded locally. Only the selected table rows are sent to the server.\nfunction tableRows(matrix){const aliases={'code':'code','account code':'code','\u79d1\u76ee\u4ee3\u7801':'code','name':'name','account name':'name','\u79d1\u76ee\u540d\u79f0':'name','group':'group','new group':'group','\u5206\u7ec4':'group','\u6240\u5c5e\u5206\u7ec4':'group','report':'report','\u62a5\u8868':'report','type':'type','\u7c7b\u578b':'type','position':'position','\u4f4d\u7f6e':'position','item key':'item_key','item_key':'item_key','group key':'group_key','group_key':'group_key','group type':'group_type','group_type':'group_type','ref':'ref','group ref':'group_ref','group_ref':'group_ref'};const normal=v=>String(v||'').trim().toLowerCase().replace(/\\s+/g,' ');const at=matrix.findIndex(r=>r.some(v=>aliases[normal(v)]==='name'));if(at<0)throw Error('Include a Name column. Optional columns: Code, Group, Report, Type, Position.');const keys=matrix[at].map(v=>aliases[normal(v)]);const mapped=keys.filter(Boolean);if(new Set(mapped).size!==mapped.length)throw Error('Duplicate recognized column names.');const rows=matrix.slice(at+1).filter(r=>r.some(v=>String(v??'').trim())).map(r=>{const o={};keys.forEach((k,i)=>{if(k&&r[i]!==undefined&&String(r[i]).trim()!==''){o[k]=['position','group_type'].includes(k)?Number(r[i]):String(r[i]).trim()}});return o});if(!rows.length||rows.length>2000)throw Error('Use a table with 1\u20132,000 rows.');return rows}\nfunction parseTable(value){const delimiter=value.includes('\\t')?'\\t':',',rows=[],row=[];let cell='',quoted=false;for(let i=0;i<value.length;i++){const c=value[i];if(c==='\"'){if(quoted&&value[i+1]==='\"'){cell+='\"';i++}else quoted=!quoted}else if(!quoted&&c===delimiter){row.push(cell);cell=''}else if(!quoted&&(c==='\\n'||c==='\\r')){if(c==='\\r'&&value[i+1]==='\\n')i++;row.push(cell);rows.push([...row]);row.length=0;cell=''}else cell+=c}if(quoted)throw Error('Unclosed quoted field.');row.push(cell);if(row.some(Boolean))rows.push(row);return tableRows(rows)}\nasync function readExcel(file){if(file.size>10*1024*1024)throw Error('Use an Excel file under 10 MB.');const bytes=new Uint8Array(await file.arrayBuffer()),view=new DataView(bytes.buffer),dec=new TextDecoder();let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(view.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('Invalid Excel ZIP file.');const count=view.getUint16(end+10,true),entries=new Map();let pos=view.getUint32(end+16,true),total=0;for(let i=0;i<count;i++){if(view.getUint32(pos,true)!==0x02014b50)throw Error('Invalid Excel archive.');const flags=view.getUint16(pos+8,true),method=view.getUint16(pos+10,true),size=view.getUint32(pos+20,true),expanded=view.getUint32(pos+24,true),n=view.getUint16(pos+28,true),extra=view.getUint16(pos+30,true),comment=view.getUint16(pos+32,true),offset=view.getUint32(pos+42,true),name=dec.decode(bytes.slice(pos+46,pos+46+n));if(flags&1)throw Error('Password protected workbooks are not supported.');total+=expanded;if(total>25*1024*1024||count>500)throw Error('Workbook is too large.');entries.set(name,{method,size,expanded,offset});pos+=46+n+extra+comment}\n async function entry(name){const e=entries.get(name);if(!e)return null;const start=e.offset+30+view.getUint16(e.offset+26,true)+view.getUint16(e.offset+28,true),raw=bytes.slice(start,start+e.size);let data;if(e.method===0)data=raw;else if(e.method===8){try{data=new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer())}catch{throw Error('This browser cannot decode this Excel file. Copy and paste its table below or save it as CSV.')}}else throw Error('Unsupported workbook compression.');if(data.length!==e.expanded)throw Error('Invalid workbook entry size.');return new DOMParser().parseFromString(dec.decode(data),'application/xml')}\n const book=await entry('xl/workbook.xml'),rels=await entry('xl/_rels/workbook.xml.rels');if(!book||!rels)throw Error('An .xlsx workbook is required.');const sheets=[...book.getElementsByTagName('sheet')],selected=sheets.find(x=>/^(coa|chart of accounts)$/i.test(x.getAttribute('name')))||sheets[0];if(!selected)throw Error('Workbook has no sheet.');const rid=selected.getAttribute('r:id'),rel=[...rels.getElementsByTagName('Relationship')].find(x=>x.getAttribute('Id')===rid);const target=rel?.getAttribute('Target')||'';if(target.includes('..')||/^\\w+:/.test(target))throw Error('Invalid workbook sheet link.');const sheet=await entry(target.startsWith('/')?target.slice(1):'xl/'+target),shared=await entry('xl/sharedStrings.xml'),strings=shared?[...shared.getElementsByTagName('si')].map(x=>x.textContent):[];if(!sheet)throw Error('Sheet not found.');const matrix=[...sheet.getElementsByTagName('row')].map(row=>{const cells=[];for(const c of row.getElementsByTagName('c')){const address=c.getAttribute('r')||'',letters=address.replace(/[0-9]/g,'');let col=0;for(const ch of letters)col=col*26+ch.charCodeAt(0)-64;const value=c.getElementsByTagName('v')[0]?.textContent||'';if(c.getElementsByTagName('f').length&&(!c.getElementsByTagName('v').length||value===''))throw Error('Recalculate this workbook in Excel and save it, or paste values. A formula has no saved result.');const kind=c.getAttribute('t');cells[col-1]=kind==='s'?strings[Number(value)]:kind==='inlineStr'?c.getElementsByTagName('is')[0]?.textContent||'':value}return cells});return tableRows(matrix)}\nlet syncDraft=null,syncRows=null,runningSync=false;\nfunction showDraft(d){syncDraft=d;const box=$('syncResult');box.replaceChildren();text(box,'p',(d.business_name||'')+' \u2014 '+(d.summary.created||0)+' new, '+(d.summary.updated||0)+' updates, '+(d.summary.unchanged||0)+' unchanged. '+d.status);const link=text(box,'a','Download Excel preview / results');link.href=d.report_path;link.download=d.report_name;link.style.color='#6b409c';for(const i of d.issues||[])text(box,'p',(i.name?i.name+': ':'')+i.message,'error');for(const w of d.warnings||[])text(box,'p',w.code+': '+w.message,'error');\nconst preview=text(box,'div','');for(const x of d.changes||[])text(preview,'pre',JSON.stringify({operation:x.operation,kind:x.kind,item_key:x.item_key,before:x.before,after:x.after,status:x.status,error:x.error},null,2));\nif(d.preview&&!d.preview.complete){text(box,'p','Showing '+d.changes.length+' of '+d.preview.total+' differences. Review all differences before approving.');const more=text(box,'button','Load all differences');more.onclick=async()=>{try{showDraft(await api('/api/coa/tasks/'+d.task_id+'?detail=true'))}catch(e){$('syncProgress').textContent=e.message}}}\n$('syncApproval').checked=false;$('syncExecute').disabled=true;$('syncRefresh').disabled=runningSync||d.status==='superseded';$('syncProgress').textContent=d.progress?d.progress.completed+' / '+d.progress.total+' processed':''}\n$('syncApproval').onchange=()=>{$('syncExecute').disabled=!$('syncApproval').checked||!syncDraft?.approval_hash||!['awaiting_confirmation','in_progress'].includes(syncDraft.status)};\n$('syncFile').onchange=async()=>{try{const file=$('syncFile').files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Use a file under 10 MB.');syncRows=/\\.xlsx$/i.test(file.name)?await readExcel(file):parseTable(await file.text());$('syncInput').value='';$('syncProgress').textContent=syncRows.length+' rows loaded from '+file.name}catch(e){syncRows=null;$('syncProgress').textContent=e.message}};\n$('syncInput').oninput=()=>{syncRows=null};\n$('syncPrepare').onclick=async()=>{const b=$('syncPrepare');b.disabled=true;try{if(!$('syncConnection').value)throw Error('Select the company and token.');const rows=syncRows||parseTable($('syncInput').value);showDraft(await api('/api/coa/prepare',{connection_id:$('syncConnection').value,rows}));await loadSyncTasks()}catch(e){$('syncProgress').textContent=e.message}finally{b.disabled=false}};\n$('syncExecute').onclick=async()=>{if(!syncDraft||!$('syncApproval').checked)return;const approved={task_id:syncDraft.task_id,approval_hash:syncDraft.approval_hash};runningSync=true;$('syncExecute').disabled=true;$('syncPrepare').disabled=true;$('syncRefresh').disabled=true;try{let d;do{d=await api('/api/coa/execute',approved);syncDraft=d;$('syncProgress').textContent=(d.progress?.completed||0)+' / '+d.summary.total+' processed';}while(d.status==='in_progress');showDraft(d);await loadSyncTasks()}catch(e){$('syncProgress').textContent=e.message+' The saved task retains progress.'}finally{runningSync=false;$('syncPrepare').disabled=false;$('syncRefresh').disabled=!syncDraft}};\n$('syncRefresh').onclick=async()=>{if(!syncDraft)return;try{showDraft(await api('/api/coa/refresh',{task_id:syncDraft.task_id}));await loadSyncTasks()}catch(e){$('syncProgress').textContent=e.message}};\nasync function loadSyncTasks(){const d=await api('/api/coa/tasks');const box=$('syncHistory');box.replaceChildren();for(const t of d.tasks){const line=text(box,'div','', 'meta');text(line,'span',t.business_name+' \u2014 '+t.status+' ('+t.created_at.slice(0,10)+') ');action(line,'Open',async()=>showDraft(await api('/api/coa/tasks/'+t.task_id)))}}\nloadSyncTasks().catch(e=>$('syncProgress').textContent=e.message);\n\n</script></body></html>\n";
let BASE='https://advisoryagency.sin.manager.cloud/api2';
let managerFetch=(...args)=>fetch(...args);
export function configureManagerApi(value,transport){const url=new URL(value);if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash||!/^\/api2\/?$/.test(url.pathname))throw new Error('MANAGER_API_BASE must be a HTTPS URL ending in /api2, without credentials or query parameters.');BASE=url.origin+'/api2';managerFetch=transport||((...args)=>fetch(...args))}
class AppError extends Error{constructor(message,status=400){super(message);this.status=status}}
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})}
async function hash(s){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('')}
async function measured(env,name,fn){return env.PERFORMANCE?env.PERFORMANCE.measure(name,fn):fn()}
async function encryptionKey(env){if(!/^[a-f0-9]{64}$/.test(env.MANAGER_TOKEN_ENCRYPTION_KEY||''))throw new AppError('Server encryption is unavailable.',503);if(!env._requestKey){env.PERFORMANCE?.increment('key_imports');env._requestKey=crypto.subtle.importKey('raw',Uint8Array.from(env.MANAGER_TOKEN_ENCRYPTION_KEY.match(/../g),x=>parseInt(x,16)),'AES-GCM',false,['encrypt','decrypt'])}return env._requestKey}
async function encrypt(env,data){env.PERFORMANCE?.increment('crypto_calls');return measured(env,'crypto_ms',async()=>{const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},await encryptionKey(env),new TextEncoder().encode(JSON.stringify(data)));return JSON.stringify({iv:Array.from(iv),cipher:Array.from(new Uint8Array(cipher))})})}
async function decrypt(env,obj){env.PERFORMANCE?.increment('crypto_calls');return measured(env,'crypto_ms',async()=>{const d=await obj.json();const raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(d.iv)},await encryptionKey(env),new Uint8Array(d.cipher));return JSON.parse(new TextDecoder().decode(raw))})}
async function scope(user){const h=await hash(user);return {prefix:'connections-v2/'+h+'/',legacy:'connections/'+h+'.json',preferred:'preferences/'+h+'.json'}}
function publicConnection(c){return {connection_id:c.id,business_name:c.name,token_name:c.token_name||null,token_name_status:c.token_name_status||'not_loaded',label:c.label||'',notes:c.notes||'',status:c.status||'unknown',verified_at:c.verified_at||null,created_at:c.created_at||null,updated_at:c.updated_at||null,last_error:c.last_error||null,token_configured:!!c.token,api_base:BASE}}
async function list(env,user){const s=await scope(user);const records=[];let cursor;do{const page=await env.BUCKET.list({prefix:s.prefix,cursor});for(const o of page.objects){const obj=await env.BUCKET.get(o.key);if(obj){const c=await decrypt(env,obj);records.push({...c,_etag:obj.etag})}}cursor=page.truncated?page.cursor:undefined}while(cursor);const old=await env.BUCKET.get(s.legacy);if(old&&!records.some(c=>c.id==='legacy')){const c=await decrypt(env,old);records.push({id:'legacy',name:c.name,token:c.token,label:'',notes:'',status:'unknown',created_at:null,updated_at:null,verified_at:null,_legacy:true,_etag:old.etag})}const pref=await env.BUCKET.get(s.preferred);let preferred=pref?(await pref.json()).id:null;const visible=records.filter(c=>!c.removed);if(!visible.some(c=>c.id===preferred))preferred=visible.length===1?visible[0].id:null;return {records:visible,preferred}}
async function save(env,user,c){const s=await scope(user);const {_etag,_legacy,...record}=c;record.updated_at=new Date().toISOString();const result=await env.BUCKET.put(s.prefix+c.id+'.json',await encrypt(env,record),_legacy?{onlyIf:{etagDoesNotMatch:'*'}}:_etag?{onlyIf:{etagMatches:_etag}}:undefined);if(result===null)throw new AppError('This connection changed in another session. Refresh and try again.',409);if(_legacy)await env.BUCKET.delete(s.legacy);return record}
async function choose(env,user,id){if(id){if(id!=='legacy'&&!UUID.test(id))throw new AppError('Connection not found.',404);const s=await scope(user);const obj=await env.BUCKET.get(s.prefix+id+'.json');if(obj){const c=await decrypt(env,obj);if(c.id===id&&!c.removed)return {...c,_etag:obj.etag};throw new AppError('Connection not found.',404)}if(id==='legacy'){const old=await env.BUCKET.get(s.legacy);if(old){const c=await decrypt(env,old);return {id:'legacy',name:c.name,token:c.token,label:'',notes:'',status:'unknown',created_at:null,updated_at:null,verified_at:null,_legacy:true,_etag:old.etag}}}throw new AppError('Connection not found.',404)}const data=await list(env,user);if(data.records.length===1)return data.records[0];if(!data.records.length)throw new AppError('Add a company connection in Evertrust Books first.');throw new AppError('Multiple companies are connected. Call list_connections and specify connection_id for this query.')}
async function manager(token,path,query={},method='GET',data=null){const url=new URL(BASE+path);for(const [k,v]of Object.entries(query)){if(Array.isArray(v)){for(const item of v)url.searchParams.append(k,String(item))}else url.searchParams.set(k,String(v))}const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),30000);try{const r=await managerFetch(url.toString(),{method,headers:{'X-API-KEY':token,'Accept':'application/json',...(data?{'Content-Type':'application/json'}:{})},...(data?{body:JSON.stringify(data)}:{}),redirect:'manual',signal:controller.signal});if(!r.ok)throw new AppError(r.status===404?'Manager resource not found.':r.status===401||r.status===403?'Manager rejected the token. Check the token and company permissions.':'Manager returned HTTP '+r.status+'.',[401,403,404].includes(r.status)?r.status:502);const body=await r.text();if(method!=='GET')return {status:r.status};if(body.length>2000000)throw new AppError('Response too large. Use a smaller page.');try{return JSON.parse(body)}catch{throw new AppError('Manager returned an unexpected response.',502)}}catch(e){if(e instanceof AppError)throw e;throw new AppError(e.name==='AbortError'?'Manager took too long to respond. Please retry.':'Could not reach Manager. Please retry.',502)}finally{clearTimeout(timer)}}

