async function readTokenName(token){const id=tokenId(token);if(id)try{const d=await manager(token,'/access-token-form/'+id);const key=d.Key??d.key;const name=d.Name??d.name;if((!key||String(key).toLowerCase()===id)&&typeof name==='string'&&name.trim()&&name.length<=500)return {token_name:name.trim(),token_name_status:'available'}}catch{}return {token_name:null,token_name_status:'unavailable'}}
async function publicConnections(records){return Promise.all(records.map(async c=>publicConnection(c.token_name===undefined?{...c,...await readTokenName(c.token)}:c)))}

function metadata(d){for(const [field,max]of [['label',120],['notes',500]])if(d[field]!==undefined&&(typeof d[field]!=='string'||d[field].length>max))throw new AppError('Invalid '+field+'.');return {label:d.label?.trim()||'',notes:d.notes?.trim()||''}}
function tokenInput(d){if(typeof d.token!=='string'||!d.token.trim()||d.token.length>10000)throw new AppError('Enter a valid access token.');return d.token.trim()}
function accountKeys(data){return (data.chartOfAccounts||[]).map(a=>a.key).filter(Boolean).sort()}
function sameCompany(c,data){if(c.name!==data.business?.name)return false;const old=c.account_keys||[];if(!old.length)return true;const next=new Set(accountKeys(data));return old.filter(k=>next.has(k)).length>=Math.max(1,Math.ceil(old.length/2))}
async function add(env,user,d){const extra=metadata(d),token=tokenInput(d);const data=await manager(token,'/chart-of-accounts');if(!data.business?.name)throw new AppError('Manager did not identify the company.');const existing=await list(env,user);if(existing.records.some(c=>c.token===token))throw new AppError('This token is already connected. Use Edit or Update token on its existing connection.',409);const now=new Date().toISOString();const c=await save(env,user,{id:crypto.randomUUID(),name:data.business.name,token,...await readTokenName(token),...extra,account_keys:accountKeys(data),status:'connected',verified_at:now,created_at:now,last_error:null});return {connected:true,connection:publicConnection(c),account_count:data.totalRecords??null}}
async function replace(env,user,id,d){const c=await choose(env,user,id);const token=tokenInput(d);const data=await manager(token,'/chart-of-accounts');if(!sameCompany(c,data))throw new AppError('This token belongs to a different company or its account identity has changed. Add it as a new connection instead.',409);const saved=await save(env,user,{...c,token,...await readTokenName(token),account_keys:accountKeys(data),...metadata({label:d.label??c.label,notes:d.notes??c.notes}),status:'connected',verified_at:new Date().toISOString(),last_error:null});return {connection:publicConnection(saved)}}
async function test(env,user,id){const c=await choose(env,user,id);try{const data=await manager(c.token,'/chart-of-accounts');if(!sameCompany(c,data))throw new AppError('The token no longer identifies the expected company.');const saved=await save(env,user,{...c,...await readTokenName(c.token),account_keys:accountKeys(data),status:'connected',verified_at:new Date().toISOString(),last_error:null});return {ok:true,connection:publicConnection(saved)}}catch(e){if(e.status===409)throw e;const saved=await save(env,user,{...c,status:'failed',last_error:e instanceof AppError?e.message:'Connection verification failed.'});return {ok:false,connection:publicConnection(saved)}}}
async function remove(env,user,id){const c=await choose(env,user,id);await save(env,user,{...c,token:null,account_keys:[],removed:true,removed_at:new Date().toISOString()});return {removed:true,connection_id:id}}
