async function coaRoutes(token,refresh=false){const cacheKey=await hash(token),cached=coaRoutesCache.get(cacheKey);if(!refresh&&cached&&Date.now()-cached.at<600000)return cached.routes;const spec=await manager(token,'');const known=Object.entries(COA_KINDS).map(([kind,path])=>({kind,path,writable:true}));const more=Object.keys(spec.paths||{}).filter(p=>p.endsWith('/{key}')&&((Object.values(SYSTEM_COA).some(x=>x.path+'/{key}'===p)&&spec.paths[p]?.get)||(/^\/(balance-sheet|profit-and-loss-statement)-/.test(p)&&/(account|group|subtotal|total|inter-account-transfers)-form\/\{key\}$/.test(p))||/^\/control-account-for-[a-z-]+-form\/\{key\}$/.test(p))).map(p=>p.slice(0,-6)).filter(p=>!Object.values(COA_KINDS).includes(p));const routes=[...known,...more.sort().map(path=>({kind:path.slice(1,-5).replaceAll('-','_'),path,writable:false}))];if(coaRoutesCache.size>=100)coaRoutesCache.delete(coaRoutesCache.keys().next().value);coaRoutesCache.set(cacheKey,{at:Date.now(),routes});return routes}
