 let obj=await env.BUCKET.get(prefix+'generation.json');
 if(!obj){const data={generation:crypto.randomUUID()};const saved=await env.BUCKET.put(prefix+'generation.json',JSON.stringify(data),{onlyIf:{etagDoesNotMatch:'*'}});if(saved)return data.generation;obj=await env.BUCKET.get(prefix+'generation.json')}
