async function coaStructure(env,user,args){return cachedCoaStructure(env,user,args)}
async function coaItem(env,user,args){const c=await choose(env,user,args.connection_id),source=await coaSource(c),routes=await coaRoutes(c.token);c._coaForms=new Map();const item=await companyItem(c,source,routes,args.item_key,args.kind);if(!item)throw new AppError('No supported COA form found.',404);return {connection_id:c.id,business_name:c.name,...publicItem(item),path:args.include_path===false?null:await ancestors(c,item,routes),validation_scope:args.include_path===false?'record_only':'record_and_ancestors'}}
