 rows.forEach((r,i)=>{const row=i+6,style=r.status==='succeeded'?5:['failed','conflict','uncertain'].includes(r.status)?6:i%2?4:0;const lines=Math.max(2,...r.values.map((v,j)=>String(v).length/[18,14,32,34,34,64][j]));data+=`<row r="${row}" ht="${Math.min(150,Math.ceil(lines)*15+6)}" customHeight="1">${r.values.map((v,j)=>cell(row,String.fromCharCode(65+j),v,style)).join('')}</row>`});
